import { useEffect, useRef } from 'react';

export default function ContextMenu({ x, y, node, groups, nodeGroups, onAddToGroup, onRemoveFromGroup, onClose }) {
  const menuRef = useRef(null);

  useEffect(() => {
    const handleClickOutside = (event) => {
      if (menuRef.current && !menuRef.current.contains(event.target)) {
        onClose();
      }
    };

    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, [onClose]);

  const isInGroup = nodeGroups.has(node.id);

  return (
    <div
      ref={menuRef}
      className="fixed z-[100] min-w-[200px] rounded-lg bg-[rgba(30,30,30,0.95)] border border-[#3a3a3a] p-2 backdrop-blur-md shadow-lg"
      style={{ left: `${x}px`, top: `${y}px` }}
    >
      <div className="px-2 py-2 text-xs text-[#a0a0a0] border-b border-[#3a3a3a]">
        {node.label}
      </div>
      {groups.length > 0 ? (
        <>
          {groups.map((group) => (
            <div
              key={group.id}
              className="px-2 py-2 cursor-pointer text-[#dcddde] text-sm rounded hover:bg-[#3a3a3a]"
              onClick={() => {
                onAddToGroup(node.id, group.id);
                onClose();
              }}
            >
              <span
                className="inline-block w-3 h-3 rounded mr-2"
                style={{ background: group.color }}
              />
              {group.name}
            </div>
          ))}
        </>
      ) : (
        <div className="px-2 py-2 text-[#666] text-xs text-center">
          Keine Gruppen vorhanden
        </div>
      )}
      {isInGroup && (
        <div
          className="px-2 py-2 cursor-pointer text-[#ff6b6b] text-sm rounded hover:bg-[#3a3a3a] border-t border-[#3a3a3a] mt-1"
          onClick={() => {
            onRemoveFromGroup(node.id);
            onClose();
          }}
        >
          Aus Gruppe entfernen
        </div>
      )}
    </div>
  );
}

