import { useState } from 'react';
import { Tabs, TabsList, TabsTrigger, TabsContent } from './ui/tabs';
import { Button } from './ui/button';
import { Input } from './ui/input';
import { Select } from './ui/select';
import { Checkbox } from './ui/checkbox';
import { Slider } from './ui/slider';
import { ChevronLeft, ChevronDown } from 'lucide-react';

export default function ControlsPanel({
  settings,
  onSettingsChange,
  onSearch,
  searchResults,
  onHighlightNode,
  groups,
  nodeGroups,
  onCreateGroup,
  onDeleteGroup,
  onShowGroupSearch,
  onExportGroups,
  onImportGroups,
  selectedColor,
  onColorSelect,
  onResetView
}) {
  const [isCollapsed, setIsCollapsed] = useState(false);
  const [isMobileOpen, setIsMobileOpen] = useState(false);
  const [groupName, setGroupName] = useState('');

  const handleCreateGroup = () => {
    if (!groupName.trim()) {
      alert('Bitte einen Gruppennamen eingeben');
      return;
    }
    onCreateGroup(groupName, selectedColor);
    setGroupName('');
  };

  const getNodeCountForGroup = (groupId) => {
    return Array.from(nodeGroups.entries()).filter(([_, gId]) => gId === groupId).length;
  };

  return (
    <div
      id="controls-panel"
      className={`absolute top-5 left-5 w-80 overflow-hidden z-40 rounded-2xl border-width:0 bg-[hsl(var(--bg-100))] border-transparent shadow-[0_0.25rem_1.25rem_hsl(var(--always-black)/3.5%),0_0_0_0.5px_hsla(var(--border-300)/0.15)] hover:shadow-[0_0.25rem_1.25rem_hsl(var(--always-black)/3.5%),0_0_0_0.5px_hsla(var(--border-200)/0.3)] focus-within:shadow-[0_0.25rem_1.25rem_hsl(var(--always-black)/7.5%),0_0_0_0.5px_hsla(var(--border-200)/0.3)] transition-transform duration-300 ${
        isCollapsed ? 'panel-collapsed' : ''
      }`}
    >
      {/* Collapse Button */}
      <button
        id="collapse-btn"
        onClick={() => setIsCollapsed(!isCollapsed)}
        className="absolute top-4 -right-10 z-50 rounded-r-lg p-2 transition-all fancy-button"
      >
        <ChevronLeft className="h-5 w-5 text-[hsl(var(--text-200))]" />
      </button>

      {/* Mobile Toggle Button */}
      <button
        id="mobile-toggle"
        onClick={() => setIsMobileOpen(!isMobileOpen)}
        className="flex w-full items-center justify-between p-4 text-[hsl(var(--text-200))] md:hidden fancy-button"
      >
        <span className="font-semibold">Steuerung</span>
        <ChevronDown
          className={`h-5 w-5 transition-transform ${isMobileOpen ? 'rotate-180' : ''}`}
        />
      </button>

      <div
        id="controls-content"
        className={`md:block ${isMobileOpen ? '' : 'hidden md:block'}`}
      >
        <Tabs defaultValue="view" className="w-full">
          <TabsList className="w-full">
            <TabsTrigger value="view">Ansicht</TabsTrigger>
            <TabsTrigger value="search">Suche</TabsTrigger>
            <TabsTrigger value="groups">Gruppen</TabsTrigger>
          </TabsList>

          {/* View Tab */}
          <TabsContent value="view" className="tab-content p-4">
            <h3 className="mb-2 text-[hsl(var(--text-200))] flex items-center text-center min-w-0 font-serif text-2xl">
              Darstellung
            </h3>
            <hr className="mb-2 mt-2 border-[hsl(var(--text-500)/0.2)]" />

            <div className="mb-2 mt-2">
              <label className="mb-2 block text-sm font-medium text-[hsl(var(--text-000))]">
                Node Typ
              </label>
              <Select
                id="node-type"
                value={settings.nodeType}
                onChange={(e) => onSettingsChange({ ...settings, nodeType: e.target.value })}
              >
                <option value="all">Alle anzeigen</option>
                <option value="antrag">Nur Anträge</option>
                <option value="supporter">Nur Supporter</option>
              </Select>
            </div>

            <div className="mb-4 space-y-2">
              <div className="flex items-center">
                <Checkbox
                  id="show-labels"
                  checked={settings.showLabels}
                  onChange={(e) =>
                    onSettingsChange({ ...settings, showLabels: e.target.checked })
                  }
                />
                <label
                  htmlFor="show-labels"
                  className="ml-2 text-sm font-medium text-[hsl(var(--text-200))]"
                >
                  Labels anzeigen
                </label>
              </div>
              <div className="flex items-center">
                <Checkbox
                  id="show-links"
                  checked={settings.showLinks}
                  onChange={(e) =>
                    onSettingsChange({ ...settings, showLinks: e.target.checked })
                  }
                />
                <label
                  htmlFor="show-links"
                  className="ml-2 text-sm font-medium text-[hsl(var(--text-200))]"
                >
                  Verbindungen anzeigen
                </label>
              </div>
            </div>

            <div className="mb-4">
              <label className="mb-2 block text-sm font-medium text-[hsl(var(--text-200))]">
                Node-Größe
              </label>
              <Slider
                id="node-size"
                min={0.5}
                max={2}
                step={0.1}
                value={settings.nodeSize}
                onChange={(e) =>
                  onSettingsChange({ ...settings, nodeSize: parseFloat(e.target.value) })
                }
              />
            </div>

            <Button onClick={onResetView} className="w-full">
              Ansicht zurücksetzen
            </Button>
          </TabsContent>

          {/* Search Tab */}
          <TabsContent value="search" className="tab-content p-4">
            <h3 className="mb-2 text-[hsl(var(--text-200))] flex items-center text-center min-w-0 font-serif text-2xl">
              Suche
            </h3>
            <hr className="mb-2 mt-2 border-[hsl(var(--text-500)/0.2)]" />

            <div className="mb-4">
              <label
                htmlFor="search"
                className="mb-2 block text-sm font-medium text-[hsl(var(--text-200))]"
              >
                Node suchen
              </label>
              <Input
                type="text"
                id="search"
                placeholder="Name oder KV eingeben..."
                onChange={(e) => onSearch(e.target.value)}
              />
            </div>

            <div id="search-results" className="space-y-1">
              {searchResults.map((node) => (
                <div
                  key={node.id}
                  className="p-2 rounded cursor-pointer text-sm mb-1 bright-container"
                  onClick={() => onHighlightNode(node.id)}
                >
                  <span className="text-[hsl(var(--text-000))]">{node.label}</span>
                  {node.sublabel && (
                    <span className="text-[hsl(var(--text-400))] text-xs ml-2">
                      ({node.sublabel})
                    </span>
                  )}
                </div>
              ))}
            </div>
          </TabsContent>

          {/* Groups Tab */}
          <TabsContent value="groups" className="tab-content p-4">
            <h3 className="mb-2 text-[hsl(var(--text-200))] flex items-center text-center min-w-0 font-serif text-2xl">
              Gruppen
            </h3>
            <hr className="mb-2 mt-2 border-[hsl(var(--text-500)/0.2)]" />

            {/* Create Group */}
            <div className="mb-4 rounded-lg p-3 bright-container">
              <label className="mb-2 block text-sm font-medium text-[hsl(var(--text-200))]">
                Neue Gruppe erstellen
              </label>
              <Input
                type="text"
                id="group-name"
                placeholder="Gruppenname"
                value={groupName}
                onChange={(e) => setGroupName(e.target.value)}
                className="mb-2"
              />
              <Button
                id="select-color-btn"
                onClick={onColorSelect}
                className="mb-2 w-full"
              >
                <span
                  id="selected-color-indicator"
                  className="mr-2 inline-block h-4 w-4 rounded"
                  style={{ background: selectedColor }}
                />
                Farbe wählen
              </Button>
              <Button id="create-group" onClick={handleCreateGroup} className="w-full">
                Gruppe erstellen
              </Button>
            </div>

            {/* Group List */}
            <div className="mb-4">
              <h4 className="mb-2 text-sm font-medium text-[hsl(var(--text-200))]">
                Aktive Gruppen
              </h4>
              <div id="group-list" className="max-h-48 space-y-2 overflow-y-auto">
                {groups.length === 0 ? (
                  <p className="text-[hsl(var(--text-400))] text-sm text-center py-4">
                    Keine Gruppen vorhanden
                  </p>
                ) : (
                  groups.map((group) => (
                    <div key={group.id} className="group-item p-3 rounded-lg bright-container">
                      <div className="flex items-center justify-between mb-2">
                        <div className="flex items-center gap-2 flex-1">
                          <div
                            style={{
                              width: '16px',
                              height: '16px',
                              background: group.color,
                              borderRadius: '4px',
                            }}
                          />
                          <span className="text-[hsl(var(--text-000))] font-medium text-sm">
                            {group.name}
                          </span>
                          <span className="text-[hsl(var(--text-400))] text-xs">
                            ({getNodeCountForGroup(group.id)})
                          </span>
                        </div>
                        <div className="flex gap-2">
                          <button
                            onClick={() => onShowGroupSearch(group.id)}
                            className="text-[hsl(var(--accent-secondary-100-full))] hover:text-[hsl(var(--accent-secondary-000-full))] text-xs fancy-button p-1 rounded"
                            title="Nodes hinzufügen"
                          >
                            <svg
                              className="w-4 h-4"
                              fill="none"
                              stroke="currentColor"
                              viewBox="0 0 24 24"
                            >
                              <path
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                strokeWidth="2"
                                d="M12 4v16m8-8H4"
                              />
                            </svg>
                          </button>
                          <button
                            onClick={() => onDeleteGroup(group.id)}
                            className="text-[hsl(var(--danger-100-full))] hover:text-[hsl(var(--danger-000-full))] text-xs fancy-button p-1 rounded"
                            title="Gruppe löschen"
                          >
                            <svg
                              className="w-4 h-4"
                              fill="none"
                              stroke="currentColor"
                              viewBox="0 0 24 24"
                            >
                              <path
                                strokeLinecap="round"
                                strokeLinejoin="round"
                                strokeWidth="2"
                                d="M19 7l-.867 12.142A2 2 0 0116.138 21H7.862a2 2 0 01-1.995-1.858L5 7m5 4v6m4-6v6m1-10V4a1 1 0 00-1-1h-4a1 1 0 00-1 1v3M4 7h16"
                              />
                            </svg>
                          </button>
                        </div>
                      </div>
                      <div className="text-xs text-[hsl(var(--text-400))]">
                        Rechtsklick auf Nodes zum Hinzufügen
                      </div>
                    </div>
                  ))
                )}
              </div>
            </div>

            {/* Import/Export */}
            <div className="space-y-2">
              <Button onClick={onExportGroups} className="w-full">
                <svg
                  className="mr-2 inline h-4 w-4"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth="2"
                    d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-4l-4 4m0 0l-4-4m4 4V4"
                  />
                </svg>
                Gruppen exportieren
              </Button>
              <label className="block w-full cursor-pointer fancy-button text-center">
                <svg
                  className="mr-2 inline h-4 w-4"
                  fill="none"
                  stroke="currentColor"
                  viewBox="0 0 24 24"
                >
                  <path
                    strokeLinecap="round"
                    strokeLinejoin="round"
                    strokeWidth="2"
                    d="M4 16v1a3 3 0 003 3h10a3 3 0 003-3v-1m-4-8l-4-4m0 0L8 8m4-4v12"
                  />
                </svg>
                Gruppen importieren
                <input
                  type="file"
                  id="import-groups"
                  accept=".json"
                  className="hidden"
                  onChange={onImportGroups}
                />
              </label>
            </div>
          </TabsContent>
        </Tabs>
      </div>
    </div>
  );
}

